import uuid
from datetime import date

from pydantic import BaseModel, ConfigDict, Field, model_validator

from career_copilot.vault.dates import check_date_range


class Education(BaseModel):
    """Education data sent by the client; the id is generated by the server."""

    degree: str = Field(min_length=1)
    institution: str = Field(min_length=1)
    location: str | None = None
    start_date: date
    end_date: date | None = Field(default=None, description="Empty means still studying")
    grade: float | None = Field(default=None, ge=0, le=10)
    description: str | None = None

    # Runs after field validation, so both dates are already `date` objects.
    @model_validator(mode="after")
    def check_end_date_not_before_start_date(self) -> "Education":
        """Reject an end date that is before the start date."""
        check_date_range(self.start_date, self.end_date)
        return self


class EducationRead(Education):
    """Education returned by the API, including its id."""

    # Allows building from ORM objects: EducationRead.model_validate(education_orm).
    model_config = ConfigDict(from_attributes=True)

    id: uuid.UUID
